package com.onrender.smartnf.health;
import java.util.*;import java.time.*;import java.sql.Date;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import static com.onrender.smartnf.health.FoodPlanModels.*;
@Service @Transactional
public class FoodPlanService {
 private final JdbcTemplate jdbc;private final HealthRepository health;private final com.onrender.smartnf.web.SimulatorMealCodec simulations;
 @org.springframework.beans.factory.annotation.Autowired public FoodPlanService(JdbcTemplate jdbc,HealthRepository health,com.onrender.smartnf.web.SimulatorMealCodec simulations){this.jdbc=jdbc;this.health=health;this.simulations=simulations;}
 public FoodPlanService(JdbcTemplate jdbc,HealthRepository health){this(jdbc,health,null);}
 private long document(){var ids=jdbc.queryForList("SELECT id FROM consent_documents WHERE consent_type='FOOD_PLAN' AND version=? AND effective_at<=CURRENT_TIMESTAMP",Long.class,DOCUMENT);if(ids.size()!=1)throw new HealthException(503,"계획 저장 안내를 준비 중입니다.");return ids.get(0);}
 public Consent consent(long member){health.lockMember(member);return jdbc.query("SELECT id,decision FROM member_consents WHERE member_id=? AND document_id=? ORDER BY id DESC LIMIT 1",(r,n)->new Consent(r.getString(2).equals("AGREED"),r.getLong(1),DOCUMENT),member,document()).stream().findFirst().orElse(new Consent(false,null,DOCUMENT));}
 public Consent changeConsent(long member,ConsentChange request){var old=consent(member);if(request==null||!DOCUMENT.equals(request.documentVersion())||!Set.of("AGREED","WITHDRAWN").contains(request.decision()==null?"":request.decision()))throw HealthException.invalid();if(!Objects.equals(old.eventId(),request.expectedEventId()))throw HealthException.conflict();if(request.decision().equals("WITHDRAWN"))erase(member);if(!old.agreed()||!request.decision().equals("AGREED"))jdbc.update("INSERT INTO member_consents(member_id,document_id,decision,recorded_at) VALUES (?,?,?,?)",member,document(),request.decision(),LocalDateTime.now(ZoneOffset.UTC));return consent(member);}
 public void erase(long member){health.lockMember(member);jdbc.update("DELETE FROM food_plan_requests WHERE member_id=?",member);jdbc.update("DELETE FROM food_plan_days WHERE member_id=?",member);}
 private void require(long member,Long event){var c=consent(member);if(!c.agreed())throw new HealthException(403,"장보기·외식 계획 저장 안내를 확인하고 동의해 주세요.");if(event!=null&&!event.equals(c.eventId()))throw HealthException.conflict();}
 private record Stored(long id,long revision,boolean deleted){}
 private Stored read(long member,LocalDate date){return jdbc.query("SELECT id,revision,deleted FROM food_plan_days WHERE member_id=? AND plan_date=?",(r,n)->new Stored(r.getLong(1),r.getLong(2),r.getBoolean(3)),member,Date.valueOf(date)).stream().findFirst().orElse(null);}
 private Day view(LocalDate date,Stored s){if(s==null||s.deleted())return new Day(date,s==null?0:s.revision(),List.of());var plans=jdbc.query("SELECT * FROM food_plan_entries WHERE day_id=? ORDER BY entry_no",(r,n)->{
  int entry=r.getInt("entry_no");var snapshot=jdbc.query("SELECT snapshot_data FROM food_plan_simulations WHERE day_id=? AND entry_no=?",(v,i)->{if(simulations==null)throw new HealthException(503,"식단 저장 기능 설정을 확인해 주세요.");return simulations.decode(v.getString(1));},s.id(),entry).stream().findFirst().orElse(null);var items=jdbc.query("SELECT * FROM food_plan_foods WHERE day_id=? AND entry_no=? ORDER BY food_no",(f,j)->{
   var tokens=jdbc.query("SELECT token_no,raw_text FROM food_plan_ingredients WHERE day_id=? AND entry_no=? AND food_no=? ORDER BY token_no",(t,k)->new Ingredient(t.getInt(1),t.getString(2)),s.id(),entry,f.getInt("food_no"));
   return new Food(f.getString("food_id"),f.getString("food_kind"),f.getString("food_name"),f.getString("basis_label"),f.getString("source_name"),f.getString("source_version"),f.getString("recipe_id"),f.getString("recipe_name"),f.getString("recipe_source"),f.getString("recipe_version"),tokens);
  },s.id(),entry);return new Plan(r.getString("plan_type"),r.getString("restaurant"),r.getString("visit_time"),r.getString("note"),items,r.getString("plan_scope"),r.getString("management_codes").isEmpty()?List.of():List.of(r.getString("management_codes").split(",")),snapshot);
 },s.id());return new Day(date,s.revision(),plans);}
 public Day day(long member,LocalDate date){require(member,null);date(date);return view(date,read(member,date));}
 public List<Count> range(long member,LocalDate from,LocalDate to){require(member,null);date(from);date(to);if(from.isAfter(to)||java.time.temporal.ChronoUnit.DAYS.between(from,to)>62)throw HealthException.invalid();return jdbc.query("SELECT d.plan_date,SUM(CASE WHEN e.plan_type='SHOPPING' AND e.plan_scope='GENERAL' THEN 1 ELSE 0 END),SUM(CASE WHEN e.plan_type='DINING' AND e.plan_scope='GENERAL' THEN 1 ELSE 0 END) ,SUM(CASE WHEN e.plan_scope='HEALTH' AND e.plan_type<>'CHOICE' THEN 1 ELSE 0 END),SUM(CASE WHEN e.plan_type='CHOICE' THEN 1 ELSE 0 END) FROM food_plan_days d JOIN food_plan_entries e ON e.day_id=d.id WHERE d.member_id=? AND d.deleted=FALSE AND d.plan_date BETWEEN ? AND ? GROUP BY d.plan_date ORDER BY d.plan_date",(r,n)->new Count(r.getDate(1).toLocalDate(),r.getInt(2),r.getInt(3),r.getInt(4),r.getInt(5)),member,Date.valueOf(from),Date.valueOf(to));}
 public Day save(long member,Save request){if(request==null)throw HealthException.invalid();return write(member,request.requestId(),request.expectedRevision(),request.consentEventId(),request.date(),validate(request.plans()),false);}
 public Day delete(long member,Delete request){if(request==null)throw HealthException.invalid();return write(member,request.requestId(),request.expectedRevision(),request.consentEventId(),request.date(),List.of(),true);}
 public static Input input(Plan p){return new Input(p.type(),p.restaurant(),p.time(),p.note(),p.items().stream().map(f->new Item(f.foodId(),f.recipeId(),f.ingredients().stream().map(Ingredient::index).toList(),f.recipeVersion())).toList(),p.scope(),p.management(),p.simulation()==null?null:p.simulation().input());}
 public Day move(long member,Move m){
  if(m==null||m.requestId()==null||m.sourceRevision()==null||m.targetRevision()==null||m.sourceRevision()<0||m.targetRevision()<0||m.consentEventId()==null||m.sourceEntry()==null||m.sourceEntry()<0||m.foodIds()==null||m.foodIds().isEmpty()||m.foodIds().size()>30||new HashSet<>(m.foodIds()).size()!=m.foodIds().size()||m.foodIds().stream().anyMatch(Objects::isNull)||!Set.of("SHOPPING","DINING").contains(m.type()==null?"":m.type()))throw HealthException.invalid();
  date(m.sourceDate());date(m.targetDate());require(member,m.consentEventId());
  // Lock is acquired by require/consent before reading either day. Both writes share this transaction.
  var normalized=validate(List.of(new Input(m.type(),m.restaurant(),m.time(),m.note(),List.of(new Item(m.foodIds().get(0),"",List.of()))))).get(0);
  String fingerprint=hash("MOVE",m.sourceDate(),m.sourceRevision(),m.consentEventId(),List.of(new Input(m.type(),normalized.restaurant(),normalized.time(),normalized.note(),m.foodIds().stream().map(id->new Item(id,"",List.of())).toList(),"GENERAL",List.of())))+"|"+m.targetDate()+"|"+m.targetRevision()+"|"+m.sourceEntry();
  String digest;try{digest=HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(fingerprint.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(java.security.NoSuchAlgorithmException e){throw new IllegalStateException(e);}
  var prior=jdbc.query("SELECT payload_hash,result_revision FROM food_plan_requests WHERE member_id=? AND request_id=?",(r,n)->new Receipt(r.getString(1),r.getLong(2)),member,m.requestId().toString()).stream().findFirst().orElse(null);
  var target=day(member,m.targetDate());if(prior!=null){if(!prior.hash().equals(digest)||target.revision()!=prior.revision())throw HealthException.conflict();return target;}
  var source=day(member,m.sourceDate());if(source.revision()!=m.sourceRevision()||target.revision()!=m.targetRevision()||m.sourceEntry()>=source.plans().size())throw HealthException.conflict();
  var from=input(source.plans().get(m.sourceEntry()));var selected=from.items().stream().filter(f->m.foodIds().contains(f.foodId())).toList();if(selected.size()!=m.foodIds().size())throw HealthException.invalid();
  var moved=new Input(m.type(),normalized.restaurant(),normalized.time(),normalized.note(),selected,from.scope(),from.management());validate(List.of(moved));
  var remaining=from.items().stream().filter(f->!m.foodIds().contains(f.foodId())).toList();var sourcePlans=new ArrayList<>(source.plans().stream().map(FoodPlanService::input).toList());if(remaining.isEmpty())sourcePlans.remove((int)m.sourceEntry());else sourcePlans.set(m.sourceEntry(),new Input(from.type(),from.restaurant(),from.time(),from.note(),remaining,from.scope(),from.management()));
  Day result;if(m.sourceDate().equals(m.targetDate())){sourcePlans.add(moved);result=write(member,UUID.randomUUID(),source.revision(),m.consentEventId(),m.sourceDate(),validate(sourcePlans),false);}else{
   var targetPlans=new ArrayList<>(target.plans().stream().map(FoodPlanService::input).toList());targetPlans.add(moved);validate(targetPlans);if(!sourcePlans.isEmpty())validate(sourcePlans);
   result=write(member,UUID.randomUUID(),target.revision(),m.consentEventId(),m.targetDate(),targetPlans,false);
   write(member,UUID.randomUUID(),source.revision(),m.consentEventId(),m.sourceDate(),sourcePlans,sourcePlans.isEmpty());
  }
  jdbc.update("INSERT INTO food_plan_requests(member_id,request_id,plan_date,operation,payload_hash,result_revision) VALUES (?,?,?,?,?,?)",member,m.requestId().toString(),Date.valueOf(m.targetDate()),"MOVE",digest,result.revision());return result;
 }
 private record Receipt(String hash,long revision){}
 private Day write(long member,UUID request,Long revision,Long event,LocalDate date,List<Input> plans,boolean remove){
  if(request==null||revision==null||revision<0||revision==Long.MAX_VALUE||event==null)throw HealthException.invalid();require(member,event);date(date);String op=remove?"DELETE":"SAVE",hash=hash(op,date,revision,event,plans);var old=read(member,date);
  var prior=jdbc.query("SELECT payload_hash,result_revision FROM food_plan_requests WHERE member_id=? AND request_id=?",(r,n)->new Receipt(r.getString(1),r.getLong(2)),member,request.toString()).stream().findFirst().orElse(null);
  if(prior!=null){if(!prior.hash().equals(hash)||old==null||old.revision()!=prior.revision()||old.deleted()!=remove)throw HealthException.conflict();return view(date,old);}
  if((old==null?0:old.revision())!=revision||remove&&(old==null||old.deleted()))throw HealthException.conflict();long next=revision+1;
  var frozen=new java.util.HashMap<Integer,SimulatorPlanModels.Saved>();var previous=view(date,old).plans();
  for(int index=0;index<plans.size();index++){var p=plans.get(index);if(p.simulation()==null)continue;if(simulations==null)throw new HealthException(503,"식단 저장 기능 설정을 확인해 주세요.");
   var same=previous.stream().filter(v->v.simulation()!=null&&v.simulation().input().equals(p.simulation())).findFirst();frozen.put(index,same.isPresent()?same.get().simulation():simulations.capture(member,p.simulation()));
  }

  if(old==null)jdbc.update("INSERT INTO food_plan_days(member_id,plan_date,revision,deleted,consent_event_id,updated_at) VALUES (?,?,?,?,?,?)",member,Date.valueOf(date),next,remove,event,LocalDateTime.now(ZoneOffset.UTC));else jdbc.update("UPDATE food_plan_days SET revision=?,deleted=?,consent_event_id=?,updated_at=? WHERE id=? AND member_id=?",next,remove,event,LocalDateTime.now(ZoneOffset.UTC),old.id(),member);
  var saved=read(member,date);jdbc.update("DELETE FROM food_plan_entries WHERE day_id=?",saved.id());int e=0;
  for(var p:plans){jdbc.update("INSERT INTO food_plan_entries(day_id,entry_no,plan_type,restaurant,visit_time,note,plan_scope,management_codes) VALUES (?,?,?,?,?,?,?,?)",saved.id(),e,p.type(),p.restaurant(),p.time(),p.note(),p.scope(),String.join(",",p.management()));if(frozen.containsKey(e))jdbc.update("INSERT INTO food_plan_simulations(day_id,entry_no,snapshot_data) VALUES(?,?,?)",saved.id(),e,simulations.encode(frozen.get(e)));int i=0;
   for(var item:p.items()){var f=FoodPlanCatalog.food(item.foodId());var r=item.recipeId().isEmpty()?null:FoodPlanCatalog.recipe(item.foodId(),item.recipeId());jdbc.update("INSERT INTO food_plan_foods(day_id,entry_no,food_no,food_id,food_kind,food_name,basis_label,source_name,source_version,recipe_id,recipe_name,recipe_source,recipe_version) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)",saved.id(),e,i,f.id(),f.kind(),f.name(),f.basis(),f.source(),f.version(),r==null?"":r.id(),r==null?"":r.name(),r==null?"":r.source(),r==null?"":r.version());
    for(int index:item.ingredientIndices())jdbc.update("INSERT INTO food_plan_ingredients(day_id,entry_no,food_no,token_no,raw_text) VALUES (?,?,?,?,?)",saved.id(),e,i,index,r.tokens().get(index));i++;
   }e++;
  }jdbc.update("INSERT INTO food_plan_requests(member_id,request_id,plan_date,operation,payload_hash,result_revision) VALUES (?,?,?,?,?,?)",member,request.toString(),Date.valueOf(date),op,hash,next);return view(date,saved);
 }
 private static String hash(String op,LocalDate date,long revision,long event,List<Input> plans){try{var bytes=new java.io.ByteArrayOutputStream();var out=new java.io.DataOutputStream(bytes);out.writeUTF(op);out.writeUTF(date.toString());out.writeLong(revision);out.writeLong(event);out.writeInt(plans.size());for(var p:plans){out.writeUTF(p.type());out.writeUTF(p.restaurant());out.writeUTF(p.time());out.writeUTF(p.note());out.writeUTF(p.scope());out.writeUTF(String.join(",",p.management()));out.writeInt(p.items().size());for(var i:p.items()){out.writeUTF(i.foodId());out.writeUTF(i.recipeId());out.writeUTF(i.recipeVersion());out.writeInt(i.ingredientIndices().size());for(int n:i.ingredientIndices())out.writeInt(n);}if(p.simulation()!=null){out.writeUTF("SIMULATOR_V1");out.writeUTF(com.onrender.smartnf.web.SimulatorMealCodec.inputHash(p.simulation()));}}return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(bytes.toByteArray()));}catch(java.io.IOException|java.security.NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}
